/// <summary>
/// Helper class for copying charges from original sales orders to return orders.
/// </summary>
public class METReturnOrderCopyChargesHelper
{

}

Method.Source:
/// <summary>
/// Copy the original sales order header charges to the specified sales table.
/// </summary>
/// <param name = "_metSalesTable">METSalesTable.</param>
/// <param name = "_salesTable">SalesTable.</param>
public static void copySOHeaderCharges(METSalesTable _metSalesTable, SalesTable _salesTable, boolean copyFromOriginalSalesId = false)
{
    MarkupTrans         markupTransOrig;
    CustInvoiceJour     custInvoiceJour;

    // Bug 354734: E2E - Sales Order - Claim/Return_SO-0256 - Disposition code 21 - Receivable line (Dollar Value) is not same in SO and Return SO
    boolean isReturnOrder = _salesTable.SalesType == SalesType::ReturnItem;

    if (copyFromOriginalSalesId)
    {
        // Copy the original SO invoiced header charges to charge only SO
        while select markupTransOrig
        exists join custInvoiceJour
            where markupTransOrig.TransTableId == custInvoiceJour.TableId
            && markupTransOrig.TransRecId == custInvoiceJour.RecId
            && custInvoiceJour.SalesId == _metSalesTable.OriginalSalesId
        {
            METReturnOrderCopyChargesHelper::createMarkupTrans(markupTransOrig, _salesTable.TableId, _salesTable.RecId, isReturnOrder);
        }
    }
    else
    {
        // Copy the original SO invoiced header charges to charge only SO
        while select markupTransOrig
        exists join custInvoiceJour
            where markupTransOrig.TransTableId == custInvoiceJour.TableId
            && markupTransOrig.TransRecId == custInvoiceJour.RecId
            && custInvoiceJour.InvoiceId == _metSalesTable.OriginalInvoice
            && custInvoiceJour.SalesId == _metSalesTable.ClaimSalesId
        {
            METReturnOrderCopyChargesHelper::createMarkupTrans(markupTransOrig, _salesTable.TableId, _salesTable.RecId, isReturnOrder);
        }
    }
}

/// <summary>
/// Copy the original sales order line charges to the specified sales line.
/// </summary>
/// <param name = "_metSalesLine">METSalesLine.</param>
/// <param name = "_originalSalesId">The original SalesId.</param>
/// <param name = "_salesLine">The SalesLine.</param>
/// <param name = "_isUpdate">Flag to indicate whether it's an update scenario.</param>
public static void copySOLineCharges(METSalesLine _metSalesLine,
    SalesId _originalSalesId,
    SalesLine _salesLine = null,
    boolean _isUpdate = false,
    boolean copyFromOriginalSalesId = false)
{
    MarkupTrans         markupTransOrig;
    CustInvoiceTrans    custInvoiceTrans;
    SalesLine           salesLine, salesLineOrig;
    SalesTable          salesTable;

    salesLine = _salesLine ? _salesLine : _metSalesLine.salesLine();

    salesTable = SalesTable::find(salesLine.SalesId);

    // Bug 354734: E2E - Sales Order - Claim/Return_SO-0256 - Disposition code 21 - Receivable line (Dollar Value) is not same in SO and Return SO
    boolean isReturnOrder = salesTable.SalesType == SalesType::ReturnItem;

    if (_isUpdate)
    {
        // If it's update scenario, delete existing charges for the line first before copying
        Markup::delete(salesLine);
    }

    while select custInvoiceTrans
            where (!_metSalesLine.InvoiceNumber || custInvoiceTrans.InvoiceId == _metSalesLine.InvoiceNumber)
            && custInvoiceTrans.SalesId == _originalSalesId
            && ((!_metSalesLine.InvoiceLineNumber || custInvoiceTrans.LineNum == _metSalesLine.InvoiceLineNumber) && custInvoiceTrans.ItemId == salesLine.ItemId)
        join markupTransOrig
            where markupTransOrig.TransTableId == custInvoiceTrans.TableId
            && markupTransOrig.TransRecId == custInvoiceTrans.RecId
    {
        if (METReturnOrderCopyChargesHelper::shouldExcludeCharge(salesTable, markupTransOrig))
        {
            continue;
        }

        real convFactor = 1;

        select firstonly RecId, SalesUnit from salesLineOrig
            where salesLineOrig.InventTransId == custInvoiceTrans.InventTransId
            && salesLineOrig.SalesId == custInvoiceTrans.SalesId;

        if (!salesLine.pdsCWUnitId() && salesLineOrig.RecId && salesLine.SalesUnit != salesLineOrig.SalesUnit)
        {
            convFactor = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(
                salesLine.itemId,
                salesLine.InventDimId,
                1,
                salesLineOrig.SalesUnit,
                salesLine.SalesUnit,
                NoYes::Yes);
        }

        METReturnOrderCopyChargesHelper::createMarkupTrans(markupTransOrig, salesLine.TableId, salesLine.RecId, isReturnOrder, convFactor);
    }
}

/// <summary>
/// Checks if a markup transaction should be excluded from copying to the return order.
/// </summary>
/// <param name = "_salesTable">The target SalesTable (return order).</param>
/// <param name = "_markupTrans">The original MarkupTrans.</param>
/// <returns>True if the charge should be excluded; otherwise, false.</returns>
private static boolean shouldExcludeCharge(SalesTable _salesTable, MarkupTrans _markupTrans)
{
    if (_salesTable.SalesType == SalesType::ReturnItem && _salesTable.ReturnReasonCodeId)
    {
        ReturnReasonCode returnReasonCode = ReturnReasonCode::find(_salesTable.ReturnReasonCodeId);
        if (returnReasonCode.METCheckReturnChargeExclusion)
        {
            MarkupTable markupTable = MarkupTable::find(_markupTrans.ModuleType, _markupTrans.MarkupCode);
            if (markupTable.METExcludeOnReturns)
            {
                return true;
            }
        }
    }
    return false;
}

/// <summary>
/// Create a new markup transaction based on the original markup transaction.
/// </summary>
/// <param name = "_markupTransOrig">The original markup transaction.</param>
/// <param name = "_transTableId">The table ID for the new transaction.</param>
/// <param name = "_transRecId">The record ID for the new transaction.</param>
/// <param name = "_isReturnOrder">is it a return order?</param>
public static void createMarkupTrans(MarkupTrans _markupTransOrig, TableId _transTableId, RecId _transRecId, boolean _isReturnOrder, real _conversionFactor = 1)
{
    MarkupValue value;
    MarkupTrans markupTrans;

    // If a charge did not actually charge anything on the original order, do not carry it onto the return order.
    if (_isReturnOrder && _markupTransOrig.CalculatedAmount == 0)
    {
        return;
    }

    markupTrans.clear();
    markupTrans                         = markupTrans.data(_markupTransOrig);
    markupTrans.RecId                   = 0;
    markupTrans.Position                = 0;

    switch (_markupTransOrig.MarkupCategory)
    {
        case MarkupCategory::Pcs:
            value = _conversionFactor ? CurrencyExchange::round(_markupTransOrig.Value / _conversionFactor, _markupTransOrig.CurrencyCode) : _markupTransOrig.Value;
            break;

        case MarkupCategory::Fixed:
            value = _markupTransOrig.MarkupCategory == MarkupCategory::Fixed ? markupTrans.Value * -1 : markupTrans.Value;
            break;

        default:
            value = _markupTransOrig.Value;
            break;
    }

    markupTrans.Value = (_markupTransOrig.METChargesMethod == METChargesMethod::TotalCases) ? _markupTransOrig.CalculatedAmount : value ;

    // Bug 354734: E2E - Sales Order - Claim/Return_SO-0256 - Disposition code 21 - Receivable line (Dollar Value) is not same in SO and Return SO
    // to avoid reselecting salesTable, previously was not working when _transRecId was the salesTable.RecId as method called for both SalesLine and SalesTable.
    if (_isReturnOrder && _markupTransOrig.MarkupCategory != MarkupCategory::Pcs)
    {
        markupTrans.Value = markupTrans.Value * -1;
    }

    markupTrans.Posted = 0;
    markupTrans.Voucher                 = '';
    markupTrans.MarkupCategory          = _markupTransOrig.MarkupCategory;
    markupTrans.TransTableId            = _transTableId;
    markupTrans.TransRecId              = _transRecId;
    markupTrans.LineNum                 = MarkupTrans::lastLineNum(markupTrans.TransTableId, markupTrans.TransRecId) + 1;

    if (_isReturnOrder)
    {
        markupTrans.METAdvancedCalculation  = _markupTransOrig.METAdvancedCalculation;
        markupTrans.CalculatedAmount        = -(_markupTransOrig.CalculatedAmount);
        markupTrans.TaxAmount               = -(_markupTransOrig.TaxAmount);
        markupTrans.Value                   = -(_markupTransOrig.Value);
    }
    else
    {
        markupTrans.METAdvancedCalculation  = NoYes::No;
        markupTrans.CalculatedAmount        = 0;
    }

    markupTrans.IsAutoCharge            = NoYes::No;

    markupTrans.insert();
}

/// <summary>
/// Create price components for the specified sales line.
/// </summary>
/// <param name = "_metSalesLine">The METSalesLine.</param>
/// <param name = "_originalSalesId">The original SalesId.</param>
/// <param name = "_salesLine">The SalesLine.</param>
public static void createPriceComponentsByLine(METSalesLine _metSalesLine, 
    SalesId _originalSalesId, 
    SalesLine _salesLine = null)
{
    CustInvoiceTrans    custInvoiceTrans;
    SalesLine           salesLine, salesLineOrig;

    salesLine = _salesLine ? _salesLine : _metSalesLine.salesLine();

    ttsbegin;

    // Copy the original SO line price components to charge only SO lines
    select firstonly salesLineOrig
        join SalesId, ItemId from custInvoiceTrans
            order by custInvoiceTrans.InvoiceId desc
            where custInvoiceTrans.InventTransId == salesLineOrig.InventTransId
            && (!_metSalesLine.InvoiceNumber || custInvoiceTrans.InvoiceId == _metSalesLine.InvoiceNumber)
            && custInvoiceTrans.SalesId == _originalSalesId
            && ((!_metSalesLine.InvoiceLineNumber || custInvoiceTrans.LineNum == _metSalesLine.InvoiceLineNumber) && custInvoiceTrans.ItemId == salesLine.ItemId);

    METSalesLinePriceComponent          salesLinePriceComponentOrig, salesLinePriceComponent;
    METSalesLinePriceComponentDetail    salesLinePriceComponentDetailOrig, salesLinePriceComponentDetail;
    METComponentCode                    componentCode;

    real convFactor = 1;


    // Bug 354734: E2E - Sales Order - Claim/Return_SO-0256 - Disposition code 21 - Receivable line (Dollar Value) is not same in SO and Return SO
    // replace while delete by delete_from
    delete_from salesLinePriceComponent
        where salesLinePriceComponent.InventTransId == salesLine.InventTransId;

    delete_from salesLinePriceComponentDetail
        where salesLinePriceComponentDetail.InventTransId == salesLine.InventTransId;

    while select salesLinePriceComponentOrig
           where salesLinePriceComponentOrig.InventTransId == salesLineOrig.InventTransId  
            // Bug 354734: E2E - Sales Order - Claim/Return_SO-0256 - Disposition code 21 - Receivable line (Dollar Value) is not same in SO and Return SO
            // join METComponentCode as component is now unique pick fee for line charges renamed to picking fee
            join PriceComponent from componentCode
           where componentCode.Component == salesLinePriceComponentOrig.Component
    {
        salesLinePriceComponent.clear();
        salesLinePriceComponent = salesLinePriceComponent.data(salesLinePriceComponentOrig);

        if (salesLine.SalesType == SalesType::ReturnItem
        // Bug 354734: E2E - Sales Order - Claim/Return_SO-0256 - Disposition code 21 - Receivable line (Dollar Value) is not same in SO and Return SO
        // DO NOT reverse discount amount for return line
        && componentCode.PriceComponent != METPriceComponent::Discounts)
        {
            salesLinePriceComponent.value = salesLinePriceComponent.Value * -1;
        }

        if(!salesLine.pdsCWUnitId() && salesLine.SalesUnit != salesLineOrig.SalesUnit)
        {
            convFactor = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(salesLine.itemId,
                                                                        salesLine.InventDimId,
                                                                        1,
                                                                        salesLineOrig.SalesUnit,
                                                                        salesLine.SalesUnit,
                                                                        NoYes::Yes);

            salesLinePriceComponent.Value = convFactor ? CurrencyExchange::round(salesLinePriceComponent.Value / convFactor, salesLine.CurrencyCode) : salesLinePriceComponent.Value;
        }

        salesLinePriceComponent.RecId           = 0;
        salesLinePriceComponent.InventTransId   = salesLine.InventTransId;

        salesLinePriceComponent.insert();
    }

    while select salesLinePriceComponentDetailOrig
           where salesLinePriceComponentDetailOrig.InventTransId == salesLineOrig.InventTransId
            // Bug 354734: E2E - Sales Order - Claim/Return_SO-0256 - Disposition code 21 - Receivable line (Dollar Value) is not same in SO and Return SO
            // To get the PriceComponent field
            join PriceComponent from componentCode
           where salesLinePriceComponentDetailOrig.Component == componentCode.Component
    {
        salesLinePriceComponentDetail.clear();
        salesLinePriceComponentDetail               = salesLinePriceComponentDetail.data(salesLinePriceComponentDetailOrig);
        salesLinePriceComponentDetail.RecId         = 0;
        salesLinePriceComponentDetail.InventTransId = salesLine.InventTransId;

        if (salesLine.SalesType == SalesType::ReturnItem
        // Bug 354734: E2E - Sales Order - Claim/Return_SO-0256 - Disposition code 21 - Receivable line (Dollar Value) is not same in SO and Return SO
        // DO NOT reverse discount amount for return line
        && componentCode.PriceComponent != METPriceComponent::Discounts)
        {
            salesLinePriceComponentDetail.Value = convFactor ? -1*CurrencyExchange::round((salesLinePriceComponentDetail.Value / convFactor),salesLine.CurrencyCode) : -1*salesLinePriceComponentDetail.Value;
        }
        else
        {
            salesLinePriceComponentDetail.Value = convFactor ? CurrencyExchange::round((salesLinePriceComponentDetail.Value / convFactor),salesLine.CurrencyCode) : salesLinePriceComponentDetail.Value;
        }

        salesLinePriceComponentDetail.VendorValue = convFactor ? CurrencyExchange::round(salesLinePriceComponentDetail.VendorValue / convFactor, salesLine.CurrencyCode) : salesLinePriceComponentDetail.VendorValue;

        salesLinePriceComponentDetail.insert();
    }

    ttscommit;
}

public static SalesId syncSalesHeaderInvoice(METSalesLine _metSalesLine, SalesLine _salesLine)
{
    METSalesTable   metSalesTable;
    #OCCRetryCount

    try
    {
        ttsbegin;
        select forupdate metSalesTable
            where metSalesTable.SalesId == _salesLine.SalesId;

        if (!metSalesTable.OriginalInvoice && _metSalesLine.InvoiceNumber)
        {
            metSalesTable.OriginalInvoice = _metSalesLine.InvoiceNumber;
            metSalesTable.ClaimSalesId = metSalesTable.originalSalesId();
            if (metSalesTable.validateWrite())
            {
                metSalesTable.update();
            }
            else 
            {
                throw Exception::Error;
            }
        }
        ttscommit;
    }
    catch (Exception::Deadlock)
    {
        if (xSession::currentRetryCount() >= #RetryNum)
        {
            throw Exception::Deadlock;
        }
        else
        {
            retry;
        }
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }

    return metSalesTable.ClaimSalesId;
}

/// <summary>
/// Synchronizes the sales lines with the original invoice information.
/// </summary>
/// <param name = "_metSalesTable"></param>
public static void syncSalesLines(METSalesTable _metSalesTable)
{
    METSalesLine metSalesLine;
    SalesLine salesLine;
    #OCCRetryCount

    try
    {
        METSalesLine    metSalesLineUpdate;
        SalesLine       salesLineUpdate;

        ttsbegin;
        while select forupdate metSalesLineUpdate
            join salesLineUpdate
            where salesLineUpdate.RecId == metSalesLineUpdate.SalesLine
               && salesLineUpdate.SalesId == _metSalesTable.SalesId
               && metSalesLineUpdate.InvoiceNumber != _metSalesTable.OriginalInvoice
        {
            metSalesLineUpdate.InvoiceNumber = _metSalesTable.OriginalInvoice;
            metSalesLineUpdate.InvoiceLineNumber = 0;
            metSalesLineUpdate.update();
        }
        ttscommit;
    }
    catch (Exception::Deadlock)
    {
        if (xSession::currentRetryCount() >= #RetryNum)
        {
            throw Exception::Deadlock;
        }
        else
        {
            retry;
        }
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
}

public static AmountCur getLineDiscountAmount(InventTransId _inventTransId)
{
    METComponentCode            metComponentCode;
    METSalesLinePriceComponent  metSalesLinePriceComponent;

    select InventTransId, sum(Value) from metSalesLinePriceComponent
        group by InventTransId
            join metComponentCode
                where metSalesLinePriceComponent.Component == metComponentCode.Component
                    && metSalesLinePriceComponent.InventTransId == _inventTransId
                    && metComponentCode.PriceComponent == METPriceComponent::Discounts;

    return metSalesLinePriceComponent.Value;
}
